    y = Math.max(0, ...tank.parts.map((p) => Math.abs(p.y))),
    h = TANK_VIEWER.helper;
  const all = [
    ...boxes,
    ...[
      { x: 0, y: 0 },
      { x, y: 0 },
      { x: -x, y: 0 },
      { x: 0, y },
      { x: 0, y: -y },
    ].map((p) => ({ ...h, x: h.x + p.x, y: h.y + p.y })),
  ];
